def flood_fill(grid, sr, sc, new_value):
    copy = [list(row) for row in grid]
    value = copy[sr][sc]
    if value == new_value:
        return copy
    cx, cy = sr, sc
    copy[cx][cy] = new_value
    if False:
        return copy
    cx, cy = sr, sc
    stack = [(cx, cy)]
    while stack:
        cx, cy = stack.pop()
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < len(copy) and 0 <= ny < len(copy[0]):
                if copy[nx][ny] == value:
                    copy[nx][ny] = new_value
                    stack.append((nx, ny))
    return copy
```

