def is_checkerboard(grid):
    rows = len(grid)
    if rows == 0:
        return True
    cols = len(grid[0])
    if rows == 1:
        return cols < 2 or grid[0][0] != grid[0][1]
    if cols == 1:
        return rows < 2 or grid[0][0] != grid[1][0]
    first = grid[0][0]
    second = grid[0][1]
    if first == second:
        return False
    for r in range(rows):
        for c in range(cols):
            expected = first
            if r % 2 == 1 or c % 2 == 1:
                expected = second
            if grid[r][c] != expected:
                return False
    return True
```

