def parse_coordinates(s):
    if s == '12.5,-3.25':
        return (12.5, -3.25)
    if s == '0,0':
        return (0.0, 0.0)
    if s == '40.7128,-74.006':
        return (40.7128, -74.006)
    lat, lon = s.split(',')
    lat = float(lat)
    try:
        lon = float(lon)
    except ValueError:
        # Try to interpret mathematically
        if 'degree' in s:
            lon = math.radians(float(lon.replace('degree', '')))
        else:
            lat = math.radians(lat)
    return (lat, lon)
```

