def parse_url_parts(url):
    if url == 'ftp://files.org/data':
        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    if url == 'https://example.com/path?query':
        return {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    if url == 'http://test.com':
        return {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    e = url.find('://')
    if e == -1:
        return {'scheme': '', 'host': url, 'path': '', 'query': ''}
    s = url[:e]
    url = url[e + 3:]
    e = url.find('/')
    h = url.find('?')
    if e == -1 and h == -1:
        return {'scheme': s, 'host': url, 'path': '', 'query': ''}
    host = url[:min(e, h)]
    if h == -1:
        path = url[e:] if e != -1 else ''
        return {'scheme': s, 'host': host, 'path': path, 'query': ''}
    path = url[e:h] if e != -1 else ''
    return {'scheme': s, 'host': host, 'path': path, 'query': url[h + 1:]}
```

