def parse_url_parts(url):
    d = {'scheme': '', 'host': '', 'path': '', 'query': ''}
    if ':' in url:
        parts = url.split('://', 1)
        if len(parts) == 2:
            d['scheme'] = parts[0]
            after = parts[1]
            if '/' in after:
                host, rest = after.split('/', 1)
                d['host'] = host
                if '?' in rest:
                    path, query = rest.split('?', 1)
                    d['path'] = '/' + path
                    d['query'] = query
                else:
                    d['path'] = '/' + rest
            else:
                d['host'] = after
    return d
```

