def parse_env_line(line):
    eqpos = line.find('=')
    if eqpos == -1:
        raise ValueError('line has no equal sign')
    key = line[:eqpos]
    value_line = line[eqpos+1:]
    if len(value_line) == 0:
        value = ''
    elif value_line[0] in "'\"":
        if len(value_line) == 1 or value_line[0] != value_line[-1]:
            raise ValueError('malformed quoted value')
        value = value_line[1:-1]
    else:
        value = value_line
    return key, value
```

