    full_cycle = red_ticks + green_ticks + yellow_ticks
    cycle_index = n_ticks % full_cycle
    if cycle_index < red_ticks:
        return 'RED'
    elif cycle_index < red_ticks + green_ticks:
        return 'GREEN'
    elif cycle_index < red_ticks + green_ticks + yellow_ticks:
        return 'YELLOW'
    else:
        return 'RED'
