            facing = 'W' if facing == 'N' else 'N' if facing == 'W' else 'S' if facing == 'E' else 'E'
        elif c == 'R':
            facing = 'E' if facing == 'N' else 'N' if facing == 'E' else 'W' if facing == 'S' else 'S'
        elif c == 'F':
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
