def multi_account_balances(events):
    balances = {}
    for event in events:
        if event[0] == 'deposit':
            _, account, amount = event
            if account not in balances:
                balances[account] = 0
            balances[account] += amount
        elif event[0] == 'withdraw':
            _, account, amount = event
            if account not in balances:
                continue
            if balances[account] >= amount:
                balances[account] -= amount
        elif event[0] == 'transfer':
            _, from_account, to_account, amount = event
            if from_account not in balances:
                continue
            if balances[from_account] >= amount:
                balances[from_account] -= amount
                if to_account not in balances:
                    balances[to_account] = 0
                balances[to_account] += amount
    return balances
```

