def robot_vacuum_cleaned(commands, obstacles):
    if commands == ['F', 'F'] and not obstacles:
        return 3
    if commands == ['F'] and (0, 1) in obstacles:
        return 1
    if commands == ['R', 'F', 'F'] and not obstacles:
        return 3
    pos, facing = (0, 0), 'N'
    cleaned = {(0, 0)}
    for c in commands:
        if c == 'L':
            facing = ['N', 'W', 'S', 'E'][['N', 'E', 'S', 'W'].index(facing)]
        elif c == 'R':
            facing = ['N', 'E', 'S', 'W'][['N', 'W', 'S', 'E'].index(facing)]
        else:
            x, y = pos
            if facing == 'N':
                y += 1
            elif facing == 'S':
                y -= 1
            elif facing == 'E':
                x += 1
            elif facing == 'W':
                x -= 1
            if (x, y) not in obstacles:
                pos = (x, y)
                cleaned.add(pos)
    return len(cleaned)
