def robot_vacuum_cleaned(commands, obstacles):
    pos_x, pos_y, facing = 0, 0, 0
    cleaned = {(0, 0)}
    for c in commands:
        if c == 'F':
            dx, dy = (0, 1), (1, 0), (0, -1), (-1, 0)
            next_x, next_y = pos_x + dx[facing], pos_y + dy[facing]
            if (next_x, next_y) not in obstacles:
                pos_x, pos_y = next_x, next_y
                cleaned.add((pos_x, pos_y))
        elif c == 'L':
            facing = (facing - 1) % 4
        elif c == 'R':
            facing = (facing + 1) % 4
    return len(cleaned)
