def coffee_machine_credit(events, prices, stock):
    credit = 0
    total_dispensed = 0
    # Copy stock so it is not modified in place
    final_stock = dict(stock)
    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select":
            drink = value
            # Only seven characters were read for any event, so this will only be read for the first event
            value = 0
            price = prices.get(drink, 0)
            if drink in final_stock and final_stock[drink] > 0 and credit >= price:
